mapper.update:
update member_order_info
set user_id=#{userId}
where order_id = #{orderId}
  and deleted = 0
  and status in (0, 1)

mapper.select:
select * from member_order_info where deleted = 0 and status in (0,1) and end_time>now() and room_id in
#{item}
order by order_id asc

select *
from member_order_info
where deleted = 0
  and user_id = #{userId}
  and status = #{status}

select c.clear_id, o.order_id, o.order_no, o.store_id, s.store_name, o.room_id, r.room_name, r.type roomType, o.end_time orderEndTime, c.status, c.start_time, c.finish_time from member_clear_info c left join member_store_info s ON s.store_id = c.store_id left join member_order_info o ON c.order_id = o.order_id left join member_room_info r ON r.room_id = o.room_id where c.deleted = 0 and o.status !=3 and c.store_id in (select store_id from member_store_user where user_id=#{userId} and type=14 and deleted=0)
and o.store_id=#{storeId}
and to_days(o.create_time) >= to_days(#{startTime}) and to_days(o.create_time) <= to_days(#{endTime})
and c.status=#{status}
and ( c.user_id=#{userId} or c.user_id is null)
and c.user_id=#{userId}
order by c.create_time desc

select * from member_order_info where deleted = 0 and room_id = #{roomId} and status in (0, 1) and end_time>now()
and order_id!=#{ignoreOrderId}
order by start_time asc

select o.order_id , o.order_no , s.store_id , s.store_name , r.room_id , r.price , r.type roomType , r.room_name , o.user_id , m.nickname , o.start_time as startTime , o.end_time , ROUND(TIMESTAMPDIFF(SECOND, o.start_time,o.end_time) / 3600, 1) AS orderHour , o.pay_price , o.pay_type , coupon.coupon_name , o.refund_price , o.status , o.create_time as createTime from member_order_info o left join member_store_info s ON o.store_id = s.store_id left join member_room_info r ON r.room_id = o.room_id left join member_user m ON m.id = o.user_id left join member_coupon_info coupon ON coupon.coupon_id=o.coupon_id where o.deleted = 0
and o.user_id=#{userId}
and o.store_id in (${storeIds})
and o.store_id=#{storeId}
and o.status=#{status}
order by ${orderColumn} desc
order by o.order_id desc

select o.order_id , o.order_no , o.order_key , r.room_name , r.price roomPrice , r.work_price workPrice , gateway.device_id gatewayId , device.device_data lockData , o.room_id , o.store_id , r.type roomType , s.store_name , s.lat , s.lon , s.address , o.user_id , o.start_time , o.end_time , ROUND(TIMESTAMPDIFF(SECOND, o.start_time,o.end_time) / 3600, 1) AS orderHour , o.price , o.pay_price , o.refund_price , o.pay_type , s.wifi_info , s.kefu_phone , c.coupon_name , o.status , o.create_time from member_order_info o left join member_store_info s ON o.store_id = s.store_id left join member_room_info r ON r.room_id = o.room_id left join member_user m ON m.id = o.user_id left join member_coupon_info c ON o.coupon_id = c.coupon_id left join member_device_info device ON device.room_id=r.room_id and device.type=5 and device.deleted=0 left join member_device_info gateway ON gateway.room_id=r.room_id and gateway.type=6 and gateway.deleted=0 where o.deleted = 0
and o.order_id = #{orderId}
and o.order_key = #{orderKey}
and o.user_id=#{userId} and o.end_time>now() and o.status in (0,1) order by o.create_time DESC limit 1

select ifnull(sum(price),0) from member_pay_order where deleted=0 AND pay_status=1 AND refund_price=0
AND store_id IN

    #{item}


    AND store_id=#{storeId}

select count(1) from member_order_info where deleted=0 AND status!=3
AND store_id IN

    #{item}


    AND store_id=#{storeId}

select count(1) from member_order_info where deleted = 0 and status = 1 and room_id = #{roomId}
and order_id !=#{ignoreOrderId}
and start_time <= now() and end_time > now()

SELECT COUNT(1)
FROM member_order_info
WHERE deleted = 0
AND room_id = #{roomId}
AND (
    (#{startTime} >= start_time - INTERVAL #{clearTime} MINUTE AND #{startTime} < end_time) OR
    (#{endTime} > start_time AND #{endTime} <= end_time + INTERVAL #{clearTime} MINUTE) OR
    (#{startTime} <= start_time AND #{endTime} >= end_time)
)

    and order_id !=#{ignoreOrderId}
